/**
 * Platform billing (SUPER_ADMIN): plans, one subscription per company and
 * monthly per-seat invoices. Seats = the company's active employees.
 *
 * Invoices are generated by the `platform.invoices` job for the previous
 * month (idempotent: one invoice per company per period). A subscription
 * becomes PAST_DUE when an invoice is still unpaid 15 days after its period
 * ends, and returns to ACTIVE once nothing overdue remains.
 *
 * TODO(payments): Razorpay/Stripe collection — invoices are marked PAID manually today.
 */
import { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma';
import { notify } from '../lib/notify';
import { istNow } from '../lib/scheduler';
import { ApiError } from '../utils/http';
import { addDays, employeeIdsWithRoles, isoDay, monthStart, utcDay } from '../utils/people';

export const GRACE_DAYS = 15;
const ALL_MODULES = [
  'core', 'attendance', 'leave', 'payroll', 'expenses', 'timesheets', 'travel', 'performance', 'recruitment',
  'onboarding', 'exit', 'assets', 'learning', 'surveys', 'recognition', 'integrations',
];

const DEFAULT_PLANS = [
  { code: 'FREE', name: 'Free', pricePerEmployee: 0, maxEmployees: 10, features: ['core', 'attendance', 'leave', 'expenses', 'recognition'] },
  {
    code: 'STANDARD',
    name: 'Standard',
    pricePerEmployee: 99,
    maxEmployees: 500,
    features: ['core', 'attendance', 'leave', 'payroll', 'expenses', 'timesheets', 'travel', 'performance', 'onboarding', 'exit', 'assets', 'recognition'],
  },
  { code: 'ENTERPRISE', name: 'Enterprise', pricePerEmployee: 199, maxEmployees: 0, features: ALL_MODULES },
];

export interface PlanInput {
  code: string;
  name: string;
  pricePerEmployee: number;
  maxEmployees?: number;
  features?: string[];
  isActive?: boolean;
}

export interface SubscriptionInput {
  planId: string;
  status?: string;
  trialEndsOn?: Date | null;
  renewsOn?: Date | null;
}

/** Creates the FREE / STANDARD / ENTERPRISE plans once (never overwrites edits). */
export async function ensureDefaultPlans(): Promise<void> {
  const existing = await prisma.plan.findMany({ where: { code: { in: DEFAULT_PLANS.map((p) => p.code) } }, select: { code: true } });
  const missing = DEFAULT_PLANS.filter((p) => !existing.some((e) => e.code === p.code));
  if (missing.length > 0) await prisma.plan.createMany({ data: missing, skipDuplicates: true });
}

export const activeEmployeeCount = (companyId: string) => prisma.employee.count({ where: { companyId, isActive: true } });

// ---- Plans ----

export async function listPlans() {
  await ensureDefaultPlans();
  const plans = await prisma.plan.findMany({
    orderBy: [{ isActive: 'desc' }, { pricePerEmployee: 'asc' }],
    include: { _count: { select: { subscriptions: true } } },
  });
  return plans.map(({ _count, ...p }) => ({ ...p, subscriptions: _count.subscriptions }));
}

export async function getPlan(id: string) {
  const plan = await prisma.plan.findUnique({ where: { id } });
  if (!plan) throw ApiError.notFound('Plan not found');
  return plan;
}

export async function createPlan(input: PlanInput) {
  try {
    return await prisma.plan.create({ data: { ...input, features: input.features ?? [] } });
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
      throw ApiError.conflict(`Plan code ${input.code} already exists`);
    }
    throw error;
  }
}

export async function updatePlan(id: string, data: Partial<Omit<PlanInput, 'code'>>) {
  await getPlan(id);
  return prisma.plan.update({ where: { id }, data });
}

/** Deletes an unused plan; a plan with subscriptions can only be deactivated. */
export async function deletePlan(id: string) {
  const plan = await getPlan(id);
  const used = await prisma.subscription.count({ where: { planId: id } });
  if (used > 0) throw ApiError.conflict(`${plan.code} has ${used} subscription(s) — deactivate it instead`);
  await prisma.plan.delete({ where: { id } });
  return plan;
}

// ---- Subscriptions ----

/** Every company with its subscription (if any), seats used and outstanding invoices. */
export async function listSubscriptions() {
  const companies = await prisma.company.findMany({
    orderBy: { name: 'asc' },
    select: {
      id: true,
      name: true,
      code: true,
      isActive: true,
      subscription: { include: { plan: true } },
      _count: { select: { employees: { where: { isActive: true } } } },
      invoices: { where: { status: 'DUE' }, select: { amount: true } },
    },
  });
  return companies.map(({ _count, invoices, ...c }) => ({
    ...c,
    seatsUsed: _count.employees,
    seatLimit: c.subscription?.plan.maxEmployees || null,
    outstanding: invoices.reduce((s, i) => s + i.amount, 0),
  }));
}

export async function assignSubscription(companyId: string, input: SubscriptionInput) {
  const company = await prisma.company.findUnique({ where: { id: companyId }, select: { id: true } });
  if (!company) throw ApiError.notFound('Company not found');
  const plan = await getPlan(input.planId);
  if (!plan.isActive) throw ApiError.badRequest(`${plan.name} is not an active plan`);
  const seats = await activeEmployeeCount(companyId);
  if (plan.maxEmployees > 0 && seats > plan.maxEmployees) {
    throw ApiError.badRequest(`The company has ${seats} active employees — ${plan.name} allows ${plan.maxEmployees}`);
  }
  const status = input.status ?? 'TRIAL';
  const trialEndsOn = input.trialEndsOn !== undefined ? input.trialEndsOn : status === 'TRIAL' ? addDays(utcDay(new Date()), 30) : null;
  const before = await prisma.subscription.findUnique({ where: { companyId } });
  const subscription = await prisma.subscription.upsert({
    where: { companyId },
    create: { companyId, planId: plan.id, status, seats, trialEndsOn, renewsOn: input.renewsOn ?? null },
    update: {
      planId: plan.id,
      status,
      seats,
      trialEndsOn,
      ...(input.renewsOn !== undefined ? { renewsOn: input.renewsOn } : {}),
    },
    include: { plan: true },
  });
  return { before, subscription };
}

export async function updateSubscription(companyId: string, data: Partial<SubscriptionInput>) {
  const before = await prisma.subscription.findUnique({ where: { companyId } });
  if (!before) throw ApiError.notFound('Company has no subscription — assign a plan first');
  if (data.planId) return assignSubscription(companyId, { status: before.status, ...data, planId: data.planId });
  const subscription = await prisma.subscription.update({ where: { companyId }, data, include: { plan: true } });
  return { before, subscription };
}

/**
 * Throws 400 when adding `adding` active employees would exceed the
 * company's plan limit. No subscription (or maxEmployees = 0) = unlimited.
 */
export async function assertSeatAvailable(companyId: string, adding = 1): Promise<void> {
  const subscription = await prisma.subscription.findUnique({ where: { companyId }, include: { plan: true } });
  if (!subscription || subscription.plan.maxEmployees <= 0) return;
  const used = await activeEmployeeCount(companyId);
  if (used + adding > subscription.plan.maxEmployees) {
    throw ApiError.badRequest(
      `Your ${subscription.plan.name} plan allows up to ${subscription.plan.maxEmployees} active employees (currently ${used}). ` +
        'Upgrade the plan to add more.'
    );
  }
}

// ---- Invoices ----

export async function listInvoices(filter: { companyId?: string; status?: string }) {
  return prisma.invoice.findMany({
    where: { ...(filter.companyId ? { companyId: filter.companyId } : {}), ...(filter.status ? { status: filter.status } : {}) },
    include: { company: { select: { id: true, name: true, code: true } } },
    orderBy: [{ period: 'desc' }, { createdAt: 'desc' }],
    take: 500,
  });
}

/** Last day of the invoice period + the grace window. */
export const overdueAfter = (period: Date) => addDays(new Date(Date.UTC(period.getUTCFullYear(), period.getUTCMonth() + 1, 0)), GRACE_DAYS);

export async function setInvoiceStatus(id: string, status: 'PAID' | 'VOID' | 'DUE', paidOn?: Date) {
  const before = await prisma.invoice.findUnique({ where: { id } });
  if (!before) throw ApiError.notFound('Invoice not found');
  if (before.status === status) throw ApiError.badRequest(`Invoice is already ${status.toLowerCase()}`);
  // TODO(payments): Razorpay/Stripe collection — mark PAID from the payment webhook instead of manually.
  const invoice = await prisma.invoice.update({
    where: { id },
    data: { status, paidOn: status === 'PAID' ? (paidOn ?? new Date()) : null },
  });
  await refreshPastDue(invoice.companyId);
  return { before, invoice };
}

/** PAST_DUE ⇄ ACTIVE for one company, from its overdue invoices. */
async function refreshPastDue(companyId: string, today = utcDay(new Date())): Promise<void> {
  const subscription = await prisma.subscription.findUnique({ where: { companyId } });
  if (!subscription || subscription.status === 'CANCELLED' || subscription.status === 'TRIAL') return;
  const due = await prisma.invoice.findMany({ where: { companyId, status: 'DUE' }, select: { period: true } });
  const overdue = due.some((i) => today > overdueAfter(i.period));
  if (overdue && subscription.status === 'ACTIVE') {
    await prisma.subscription.update({ where: { companyId }, data: { status: 'PAST_DUE' } });
    await notify(companyId, await employeeIdsWithRoles(companyId, ['ADMIN']), {
      event: 'billing.past_due',
      title: 'Subscription payment overdue',
      body: `An invoice is unpaid more than ${GRACE_DAYS} days after its period ended.`,
      link: '/billing',
      email: true,
    });
  } else if (!overdue && subscription.status === 'PAST_DUE') {
    await prisma.subscription.update({ where: { companyId }, data: { status: 'ACTIVE' } });
  }
}

/** "YYYY-MM" of the month before the current IST month. */
export function previousMonthKey(now = new Date()): string {
  const ist = istNow(now);
  return new Date(Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth() - 1, 1)).toISOString().slice(0, 7);
}

/**
 * Bills `monthKey` for every ACTIVE / PAST_DUE subscription (seats × price).
 * Idempotent: the (companyId, period) unique key means re-runs skip
 * companies already invoiced. Free (zero-amount) plans are not invoiced.
 */
export async function generateInvoices(monthKey = previousMonthKey()) {
  const period = monthStart(monthKey);
  const subscriptions = await prisma.subscription.findMany({
    where: { status: { in: ['ACTIVE', 'PAST_DUE'] }, company: { isActive: true } },
    include: { plan: true },
  });
  let created = 0;
  let skipped = 0;
  for (const s of subscriptions) {
    const seats = await activeEmployeeCount(s.companyId);
    await prisma.subscription.update({ where: { id: s.id }, data: { seats } });
    const amount = Math.round(seats * s.plan.pricePerEmployee * 100) / 100;
    if (amount <= 0) {
      skipped++;
      continue;
    }
    try {
      await prisma.invoice.create({ data: { companyId: s.companyId, period, seats, amount, status: 'DUE' } });
      created++;
      await notify(s.companyId, await employeeIdsWithRoles(s.companyId, ['ADMIN']), {
        event: 'billing.invoice',
        title: `Invoice for ${monthKey}`,
        body: `${seats} seats × ₹${s.plan.pricePerEmployee} = ₹${amount} (${s.plan.name}).`,
        link: '/billing',
        email: true,
      });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') skipped++;
      else throw error;
    }
  }
  return { period: isoDay(period), created, skipped };
}

/** Daily: ends expired trials (→ ACTIVE), refreshes seat counts and PAST_DUE flags. */
export async function dailySubscriptionSweep() {
  const today = utcDay(new Date());
  const subscriptions = await prisma.subscription.findMany({ where: { status: { not: 'CANCELLED' } } });
  for (const s of subscriptions) {
    const seats = await activeEmployeeCount(s.companyId);
    if (s.status === 'TRIAL' && s.trialEndsOn && s.trialEndsOn < today) {
      await prisma.subscription.update({ where: { id: s.id }, data: { status: 'ACTIVE', seats } });
      await notify(s.companyId, await employeeIdsWithRoles(s.companyId, ['ADMIN']), {
        event: 'billing.trial_ended',
        title: 'Your trial has ended',
        body: 'The subscription is now active and will be invoiced monthly per active employee.',
        link: '/billing',
        email: true,
      });
    } else if (s.seats !== seats) {
      await prisma.subscription.update({ where: { id: s.id }, data: { seats } });
    }
    await refreshPastDue(s.companyId, today);
  }
}

// ---- Company view ----

export async function companyBilling(companyId: string) {
  const [subscription, seatsUsed, invoices] = await Promise.all([
    prisma.subscription.findUnique({ where: { companyId }, include: { plan: true } }),
    activeEmployeeCount(companyId),
    prisma.invoice.findMany({ where: { companyId }, orderBy: { period: 'desc' }, take: 36 }),
  ]);
  return {
    subscription,
    plan: subscription?.plan ?? null,
    seatsUsed,
    seatLimit: subscription && subscription.plan.maxEmployees > 0 ? subscription.plan.maxEmployees : null,
    outstanding: invoices.filter((i) => i.status === 'DUE').reduce((s, i) => s + i.amount, 0),
    invoices: invoices.map((i) => ({ ...i, overdue: i.status === 'DUE' && utcDay(new Date()) > overdueAfter(i.period) })),
  };
}
